### Priority Ranking:

```python
import numpy as np
import matplotlib.pyplot as plt

print("\n" + "="*70)
print("DEEP LEARNING HYPERPARAMETERS")
print("="*70)

hyperparameters = {
    "🔴 Critical (Tune First)": {
        "learning_rate": {
            "description": "Step size for optimizer",
            "typical_range": "1e-5 to 1e-1",
            "impact": "10-100x performance difference",
            "search": "Log scale"
        },
        "batch_size": {
            "description": "Samples per gradient update",
            "typical_range": "16 to 512",
            "impact": "Affects convergence & memory",
            "search": "Powers of 2"
        },
        "optimizer": {
            "description": "Optimization algorithm",
            "typical_range": "Adam, AdamW, SGD+momentum",
            "impact": "Major effect on training",
            "search": "Categorical"
        }
    },

    "🟠 Important (Tune Second)": {
        "weight_decay": {
            "description": "L2 regularization strength",
            "typical_range": "0 to 1e-2",
            "impact": "Prevents overfitting",
            "search": "Log scale"
        },
        "dropout_rate": {
            "description": "Dropout probability",
            "typical_range": "0 to 0.5",
            "impact": "Regularization",
            "search": "Linear scale"
        },
        "lr_schedule": {
            "description": "Learning rate schedule",
            "typical_range": "Cosine, Step, Exponential",
            "impact": "Final convergence quality",
            "search": "Categorical + params"
        }
    },

    "🟡 Secondary (Tune If Time)": {
        "warmup_steps": {
            "description": "LR warmup duration",
            "typical_range": "0 to 10% of training",
            "impact": "Training stability",
            "search": "Linear scale"
        },
        "gradient_clip": {
            "description": "Max gradient norm",
            "typical_range": "0.5 to 5.0",
            "impact": "Prevents exploding gradients",
            "search": "Log scale"
        },
        "label_smoothing": {
            "description": "Soft labels (1-ε, ε/(K-1))",
            "typical_range": "0 to 0.2",
            "impact": "Better calibration",
            "search": "Linear scale"
        }
    },

    "⚪ Model-Specific": {
        "num_layers": {
            "description": "Network depth",
            "typical_range": "Model dependent",
            "impact": "Capacity vs overfitting",
            "search": "Integer"
        },
        "hidden_size": {
            "description": "Layer width",
            "typical_range": "Model dependent",
            "impact": "Capacity vs computation",
            "search": "Powers of 2"
        },
        "attention_heads": {
            "description": "Multi-head attention (Transformers)",
            "typical_range": "4, 8, 12, 16",
            "impact": "Model expressiveness",
            "search": "Factors of hidden_size"
        }
    }
}

for category, params in hyperparameters.items():
    print(f"\n{category}")
    print("-" * 70)
    for name, info in params.items():
        print(f"\n  {name}:")
        for key, value in info.items():
            print(f"    • {key}: {value}")

print("\n" + "="*70)
print("💡 Tuning Strategy:")
print("""
1. Start with learning rate (biggest impact!)
2. Then batch size and optimizer
3. Add regularization (weight decay, dropout)
4. Fine-tune schedule and warmup
5. Architecture search last (expensive!)
""")
print("="*70)
```
